/* JTHRAH_TRUSTINDEX_REVIEWS_START */
(function(){
  "use strict";

  if(window.__JTHRAH_TRUSTINDEX_REVIEWS__) return;
  window.__JTHRAH_TRUSTINDEX_REVIEWS__ = true;

  var SECTION_ID = "jth-trustindex-reviews";
  var TRUSTINDEX_SRC = "https://cdn.trustindex.io/loader.js?d487df08305524413a96b2a3e82";

  function isHomePage(){
    var path = (window.location.pathname || "/").replace(/\/+$/,"") || "/";
    return path === "/" || path === "/ar" || path === "/en";
  }

  function findWhySection(){
    return document.getElementById("jth-why") || document.querySelector(".jth-why-section");
  }

  function findFooter(){
    return document.getElementById("jth-premium-footer") ||
           document.querySelector(".jth-custom-footer") ||
           document.querySelector("footer");
  }

  function placeWidget(){
    if(!document.body || !isHomePage()) return;
    if(document.getElementById(SECTION_ID)) return;

    var section = document.createElement("section");
    section.id = SECTION_ID;
    section.setAttribute("aria-label","Google Reviews");

    var inner = document.createElement("div");
    inner.className = "jth-trustindex-inner";
    section.appendChild(inner);

    var why = findWhySection();
    var footer = findFooter();

    if(why && why.parentNode){
      why.parentNode.insertBefore(section, why.nextSibling);
    }else if(footer && footer.parentNode){
      footer.parentNode.insertBefore(section, footer);
    }else{
      document.body.appendChild(section);
    }

    var script = document.createElement("script");
    script.src = TRUSTINDEX_SRC;
    script.async = true;
    script.defer = true;
    inner.appendChild(script);
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", placeWidget, {once:true});
  }else{
    placeWidget();
  }
})();
/* JTHRAH_TRUSTINDEX_REVIEWS_END */
